			case 'tutorial_settings_appearance_title': return 'Erscheinungsbild';
			case 'tutorial_settings_appearance_text': return 'Hier kannst du den Dark Mode aktivieren und die Farben der App ganz nach deinem Geschmack anpassen.';
			case 'tutorial_settings_updates_title': return 'Updates & Versionen';
			case 'tutorial_settings_updates_text': return 'Prüfe hier auf neue Updates oder wechsle zu einer älteren Version zurück, falls mal etwas nicht klappt.';
			case 'tutorial_settings_general_title': return 'Allgemein';
			case 'tutorial_settings_general_text': return 'Ändere die Sprache oder starte das gesamte Tutorial neu, falls du dir alles noch einmal ansehen möchtest.';
			case 'tutorial_settings_data_title': return 'Datenverwaltung';
			case 'tutorial_settings_data_text': return 'Erstelle manuelle Backups deiner Dexe (Exportieren) oder lade alte Backups wieder in die App (Importieren).';
			case 'tutorial_settings_cloud_title': return 'Cloud-Synchronisation';
			case 'tutorial_settings_cloud_text': return 'Verbinde dein Google Drive, um deine Daten sicher in der Cloud zu speichern und zwischen deinen Geräten zu synchronisieren!';
			case 'tutorial_settings_community_title': return 'Community & Support';
			case 'tutorial_settings_community_text': return 'Du hast einen Bug gefunden oder möchtest bei der Entwicklung helfen? Hier findest du alle Links!';
			case 'tutorial_settings_credits_title': return 'Danksagungen & Quellen';
			case 'tutorial_settings_credits_text': return 'PokeVault wäre ohne diese tollen Projekte nicht möglich. Schau sie dir gerne an! Das war\'s – viel Spaß mit der App!';
			default: return null;
		}
	}
}

