			case 'tutorial_settings_data_text': return 'Create manual backups of your Dexes (Export) or load old backups back into the app (Import).';
			case 'tutorial_settings_cloud_title': return 'Cloud Sync';
			case 'tutorial_settings_cloud_text': return 'Connect your Google Drive to securely save your data in the cloud and sync it across devices!';
			case 'tutorial_settings_community_title': return 'Community & Support';
			case 'tutorial_settings_community_text': return 'Found a bug or want to help with development? You can find all the links here!';
			case 'tutorial_settings_credits_title': return 'Credits & Sources';
			case 'tutorial_settings_credits_text': return 'PokeVault wouldn\'t be possible without these amazing projects. Feel free to check them out! That\'s it – have fun with the app!';
			default: return null;
		}
	}
}
